<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/adapter.php';$actor=ar_ui_require_role('STUDENT','OFFICER','SUPERVISOR','ADMIN');$error='';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){try{ar_ui_csrf();if(!password_verify((string)($_POST['current_password']??''),$actor['password_hash'])){throw new DomainException('Current password is incorrect.');}ar_transaction($pdo,fn()=>ai_password($pdo,(int)$actor['id'],$_POST['password']??'',$_POST['confirm_password']??''));$_SESSION=[];session_regenerate_id(true);redirect('auth/login.php');}catch(Throwable $e){$error=page_error($e,$errors);}}
$pageTitle='Change Password';require_once __DIR__.'/../includes/header.php';?>
<section class="panel" style="max-width:600px"><h1>Change password</h1><p>Enter your current password. After changing it, log in again; other sessions will be revoked.</p><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><form method="post"><?php csrf_field();form_fields(['current_password'=>['label'=>'Current password','type'=>'password','required'=>true,'autocomplete'=>'current-password'],'password'=>['label'=>'New password ('.PASSWORD_MIN_LENGTH.'-'.PASSWORD_MAX_LENGTH.' characters)','type'=>'password','maxlength'=>PASSWORD_MAX_LENGTH,'required'=>true,'autocomplete'=>'new-password'],'confirm_password'=>['label'=>'Confirm password','type'=>'password','maxlength'=>PASSWORD_MAX_LENGTH,'required'=>true,'autocomplete'=>'new-password']],$errors);?><button class="btn primary" type="submit">Change password</button></form></section><?php require_once __DIR__.'/../includes/footer.php';?>
